@ExtendWith(MockitoExtension.class)
class OrderServiceTest {

    @Mock
    private PaymentGateway paymentGateway;

    @Mock
    private InventoryRepository inventoryRepository;

    @InjectMocks
    private OrderService orderService;  // Mockito injects the two mocks above

    @Test
    void shouldProcessOrderWhenPaymentSucceeds() {
        var order = new Order(1L, "Laptop", 999.99);
        when(paymentGateway.charge(999.99)).thenReturn(true);  // stub behavior
        when(inventoryRepository.reserve("Laptop")).thenReturn(true);

        boolean result = orderService.processOrder(order);

        assertTrue(result);
        verify(paymentGateway).charge(999.99);  // verify interaction
        verify(inventoryRepository).reserve("Laptop");
    }
}
