@ExtendWith(MockitoExtension.class)
class PaymentServiceTest {

    @Mock
    private PaymentGateway gateway;

    @InjectMocks
    private PaymentService service;

    @Test
    void strictStubbingCatchesUnusedStub() {
        // This stub is never called in the test
        when(gateway.authorize(100.0)).thenReturn(true);
        // Strict stubbing throws UnnecessaryStubbingException here

        // Test calls a different method or different arguments
        service.refund(50.0);  // doesn't use the stub above
    }

    @Test
    void strictStubbingCatchesWrongArguments() {
        when(gateway.authorize(100.0)).thenReturn(true);  // stubbed with 100.0

        service.processPayment(200.0);  // calls authorize(200.0) - different argument!
        // Strict stubbing detects the mismatch and fails the test
    }
}
