class NotificationServiceTest {

    @Test
    void manualMockInTestMethod() {
        // Create mock inline when you need it
        EmailService emailService = Mockito.mock(EmailService.class);
        when(emailService.send(anyString())).thenReturn(true);

        var notificationService = new NotificationService(emailService);
        assertTrue(notificationService.notifyUser("user@example.com"));
    }

    @ParameterizedTest
    @ValueSource(strings = {"EmailService", "SmsService", "PushService"})
    void dynamicMockCreationInParameterizedTest(String serviceType) {
        // Create different mocks based on parameter
        Object service = switch(serviceType) {
            case "EmailService" -> Mockito.mock(EmailService.class);
            case "SmsService" -> Mockito.mock(SmsService.class);
            default -> Mockito.mock(PushNotificationService.class);
        };
        // Use the dynamically created mock in test logic
    }
}
