// Manual MockitoSession (framework-agnostic)
class ManualMockitoTest {
    private MockitoSession mockitoSession;
    private PaymentGateway gateway;

    void setup() {
        mockitoSession = Mockito.mockitoSession()
            .initMocks(this)  // initializes @Mock fields
            .strictness(Strictness.STRICT_STUBS)
            .startMocking();
        gateway = mock(PaymentGateway.class);  // or use @Mock field
    }

    void teardown() {
        mockitoSession.finishMocking();  // validates stubs, cleans up
    }
}

